'use strict';
const $=id=>document.getElementById(id),game=document.querySelector('.game');
const ROWS=9,COLS=6,COUNT=54,MINE_COUNT=10;
const sprites={cube:[[78,282],[164,282],[250,282],[78,356],[164,357],[78,431],[78,507],[78,580],[164,657]],gold:[335,282],green:[164,430],empty:[421,282],bomb:[240,355]};
let state='tutorial',step=0,board=[],started=false,mode='reveal',seconds=0,reward=0,claimed=false,tutorialFlag=false,toastTimeout;
function neighbors(i){let a=[];for(let dy=-1;dy<=1;dy++)for(let dx=-1;dx<=1;dx++){let y=Math.floor(i/COLS)+dy,x=i%COLS+dx;if((dx||dy)&&y>=0&&y<ROWS&&x>=0&&x<COLS)a.push(y*COLS+x)}return a}
function art(type,i){let p=type==='cube'?sprites.cube[(i*7+Math.floor(i/6))%sprites.cube.length]:sprites[type];return `<span class="art" aria-hidden="true" style="background-position:${-(p[0]-35)/5.82}cqw ${-(p[1]-35)/5.82}cqw"></span>`}
function tutorial(){state='tutorial';step=0;tutorialFlag=false;game.classList.remove('playing');$('stats').hidden=true;$('modes').hidden=true;$('notice').hidden=true;$('title').textContent='Common Patterns';$('description').innerHTML="This revealed coin in the corner has one bordering block<br class='wide'> left unopened, it must be the bomb. Let's flag it!";$('primary').textContent='Next';$('secondary').textContent='Skip tutorial';renderTutorial()}
function renderTutorial(){const revealed={3:'gold',4:'empty',5:'empty',8:'bomb',9:'gold',10:'empty',11:'empty',13:'green',14:'gold',15:'gold',16:'empty',17:'empty',19:'gold',20:'empty',21:'empty',22:'empty',23:'empty',25:'green',26:'green',27:'green',28:'green',29:'gold'};$('board').innerHTML=Array.from({length:COUNT},(_,i)=>`<button class="cell" data-i="${i}" aria-label="Row ${Math.floor(i/6)+1}, column ${i%6+1}, ${i===8?'tutorial mine':revealed[i]||'unopened block'}">${art(revealed[i]||'cube',i)}${i===8&&tutorialFlag?'<span class="flagMark">⚑</span>':''}</button>`).join('')}
function setMode(m){mode=m;for(const x of ['flag','reveal']){$(x).classList.toggle('active',x===m);$(x).setAttribute('aria-pressed',String(x===m))}}
function start(){state='playing';started=false;seconds=0;reward=0;claimed=false;board=Array.from({length:COUNT},()=>({mine:false,revealed:false,flagged:false,n:0}));game.classList.add('playing');$('stats').hidden=false;$('modes').hidden=false;$('notice').hidden=false;$('title').textContent='Find your fortune';$('description').textContent='Reveal coins. Flag mines. Clear the field.';$('primary').textContent='New game';$('secondary').textContent='How to play';setMode('reveal');$('dialog').close();render()}
function seed(first){const safe=new Set([first,...neighbors(first)]),pool=Array.from({length:COUNT},(_,i)=>i).filter(i=>!safe.has(i));for(let n=0;n<MINE_COUNT;n++){const j=n+Math.floor(Math.random()*(pool.length-n));[pool[n],pool[j]]=[pool[j],pool[n]];board[pool[n]].mine=true}board.forEach((c,i)=>c.n=neighbors(i).filter(k=>board[k].mine).length);started=true}
function render(){let flags=0,coins=0;$('board').innerHTML=board.map((c,i)=>{if(c.flagged)flags++;if(c.revealed&&!c.mine)coins++;let type=c.revealed?(c.mine?'bomb':c.n===0?'empty':c.n===1?'gold':'green'):'cube';const label=`Row ${Math.floor(i/6)+1}, column ${i%6+1}, ${c.flagged?'flagged':c.revealed?(c.mine?'mine':c.n+' neighboring mines'):'unopened'}`;return `<button class="cell" data-i="${i}" aria-label="${label}" ${state!=='playing'?'disabled':''}>${art(type,i)}${c.flagged&&!c.revealed?'<span class="flagMark">⚑</span>':''}${c.revealed&&!c.mine&&c.n>2?`<span class="number">${c.n}</span>`:''}</button>`}).join('');$('mines').textContent=MINE_COUNT-flags;$('coins').textContent=coins*10;$('timer').textContent=`${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`}
function act(i,flag=false){if(state!=='playing'||!Number.isInteger(i)||i<0||i>=COUNT)return;const c=board[i];if(c.revealed)return;if(flag){if(!c.flagged&&board.filter(x=>x.flagged).length>=MINE_COUNT){toast('All 10 flags are in use.');return}c.flagged=!c.flagged;render();return}if(c.flagged)return;if(!started)seed(i);if(c.mine){c.revealed=true;state='lost';board.forEach(c=>{if(c.mine)c.revealed=true});render();$('title').textContent='Mine hit!';showDialog('A little bad luck','You found a mine. Try a new field — your first reveal is always safe.',[['Try again',start],['View board',()=>{}]]);return}const queue=[i];while(queue.length){const k=queue.pop(),cell=board[k];if(cell.revealed||cell.flagged||cell.mine)continue;cell.revealed=true;if(cell.n===0)queue.push(...neighbors(k))}if(board.every(c=>c.mine||c.revealed)){state='won';reward=440;$('title').textContent='Field cleared!';showDialog('A golden sweep',`All 44 safe blocks revealed.\nYour reward: ${reward} demo coins.`,[['Collect demo reward',claim],['View board',()=>{}]]);$('primary').textContent='Collect reward'}render()}
function claim(){if(state!=='won'||claimed)return;claimed=true;showDialog('Reward collected',`${reward} demo coins collected for this round.\nThese are simulated points with no monetary value.`,[['Play again',start]]);$('primary').textContent='New game'}
function showDialog(title,body,actions){$('dialogTitle').textContent=title;$('dialogText').textContent=body;$('dialogActions').replaceChildren();actions.forEach(([label,fn])=>{const b=document.createElement('button');b.textContent=label;b.onclick=()=>{$('dialog').close();fn()};$('dialogActions').append(b)});if(!$('dialog').open)$('dialog').showModal()}
function toast(text){clearTimeout(toastTimeout);$('toast').textContent=text;$('toast').classList.add('show');toastTimeout=setTimeout(()=>$('toast').classList.remove('show'),2400)}
function newRound(){if(state==='playing'&&started){showDialog('Start a new field?','Your current round will end.',[['New game',start],['Keep playing',()=>{}]])}else start()}
$('board').onclick=e=>{const b=e.target.closest('[data-i]');if(!b)return;const i=Number(b.dataset.i);if(state==='tutorial'){if(i===8){tutorialFlag=!tutorialFlag;renderTutorial();toast(tutorialFlag?'Flag placed. This block contains a mine.':'Flag removed.')}else toast('Coins show the number of neighboring mines.');return}act(i,mode==='flag')};$('board').oncontextmenu=e=>{const b=e.target.closest('[data-i]');if(b){e.preventDefault();act(Number(b.dataset.i),true)}};
$('primary').onclick=()=>{if(state==='tutorial'){if(step++===0){tutorialFlag=true;renderTutorial();$('title').textContent='You’re ready';$('description').textContent='Coins count nearby mines. Reveal safe blocks and use Flag to mark a mine.';$('primary').textContent='Play now'}else start()}else if(state==='won'&&!claimed)claim();else newRound()};$('secondary').onclick=()=>{if(state==='tutorial')start();else showDialog('How to play','A coin’s number counts mines in the 8 surrounding blocks.\n\nReveal all 44 safe blocks to win. Use Flag mode or right-click to mark a suspected mine. Your first reveal is always safe.\n\nClear the board to collect 440 simulated demo coins.',[['Continue',()=>{}]])};$('reveal').onclick=()=>setMode('reveal');$('flag').onclick=()=>setMode('flag');$('dismiss').onclick=()=>$('dialog').close();$('menu').onclick=()=>showDialog('Game menu','GameFi prototype · 6 × 9 field · 10 mines\nRewards are simulated. No wallet or real transactions.',[['New game',newRound],['Replay tutorial',tutorial],['Continue',()=>{}]]);$('close').onclick=()=>showDialog('Leave this round?','You can start a fresh game or keep exploring the demo.',[['Back to tutorial',tutorial],['Keep playing',()=>{}]]);
setInterval(()=>{if(state==='playing'&&started){seconds++;$('timer').textContent=`${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`}},1000);
let randomSeed=74;const rand=()=>{randomSeed=(randomSeed*16807)%2147483647;return(randomSeed-1)/2147483646};for(let i=0;i<185;i++){const s=document.createElement('i');s.className='star';const size=.12+rand()*.45;s.style.cssText=`left:${rand()*100}%;top:${rand()*100}%;width:${size}cqw;height:${size}cqw;opacity:${.1+rand()*.45}`;document.querySelector('.stars').append(s)}
tutorial();
if(document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'read_game',description:'Read visible game status without exposing hidden mines.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({state,seconds,coins:state==='tutorial'?0:board.filter(c=>c.revealed&&!c.mine).length*10,cells:board.map((c,i)=>({index:i,flagged:c.flagged,revealed:c.revealed,...(c.revealed?{neighboringMines:c.n,mine:c.mine}:{})}))})})}catch{}}
